mapper.select:
select ckbgdh
from hx_ckts.ckts_wbsj_zj_dlckhwzm
where djxh = #{djxh,jdbcType=VARCHAR} and dlckhwzmhm = #{dlzmh,jdbcType=VARCHAR}

select gwxh
from hx_qx.qx_swjg_gw t
 where t.gw_dm=#{gwdm} and t.swjg_dm=#{swjgdm}

select rw.rwfqsj, lc.lcswsx_dm as lcswsxDm, lc.ssq || decode(lc.sbpc,'','','-'||lc.sbpc) as sssq, dj.nsrmc, nvl(dj.shxydm, dj.nsrsbh) as nsrsbh, rw.rwzt as rwmc, lc.ckqygllb_dm as flglcd, rw.gwmc, lc.lcslid, rw.rwfqrmc, rw.gzxid from zj_mh.mh_rwxx rw, hx_ckts.ckts_ty_ywblxx lc, hx_dj.dj_nsrxx dj where rw.lcslid = lc.lcslid and dj.djxh = lc.djxh and rw.xndbrdm = #{xndbrdm} and rw.rwstatus = '01' and rw.rwzt not like '%发放-%'
and lc.lcswsx_dm in
#{item}
and (nvl(dj.shxydm, dj.nsrsbh) like '%'||#{qybs}||'%' or dj.nsrmc like '%'||#{qybs}||'%')
and rw.rwfqsj>#{sbrqQ}
and #{sbrqZ}>rw.rwfqsj

select s.* from table(func_shzs_rwwp(
                        #{swjgDm,jdbcType=VARCHAR},
                        #{zjgwdm,jdbcType=VARCHAR},
                        #{nsrsbh,jdbcType=VARCHAR},
                        #{lcswsxDm,jdbcType=VARCHAR}
                      )) s
